        public void Serialize(
            ref JsonWriter writer,
            IProcessor value,
            IJsonFormatterResolver formatterResolver
        )
        {
            if (value?.Name == null)
            {
                writer.WriteNull();
                return;
            }
            writer.WriteBeginObject();
            writer.WritePropertyName(value.Name);
            switch (value.Name)
            {
                case "append":
                    formatterResolver
                        .GetFormatter<IAppendProcessor>()
                        .Serialize(ref writer, value as IAppendProcessor, formatterResolver);
                    break;
                case "attachment":
                    formatterResolver
                        .GetFormatter<IAttachmentProcessor>()
                        .Serialize(ref writer, value as IAttachmentProcessor, formatterResolver);
                    break;
                case "bytes":
                    formatterResolver
                        .GetFormatter<IBytesProcessor>()
