                    formatterResolver
                        .GetFormatter<INetworkDirectionProcessor>()
                        .Serialize(
                            ref writer,
                            value as INetworkDirectionProcessor,
                            formatterResolver
                        );
                    break;
                default:
                    DynamicObjectResolver
                        .ExcludeNullCamelCase.GetFormatter<IProcessor>()
                        .Serialize(ref writer, value, formatterResolver);
                    break;
